{
  "mode": "namespace",
  "namespace": "mooltrace",
  "namespaceStatus": "ready",
  "namespaceDescription": "MoolTrace catches when your health AI's sources quietly rest on a flagged or retracted study, even three links deep. Pre-merge check for health-AI answer fixtures. Prefer the CLI `mooltrace batch` in CI. check_answer returns pass, warn, or block with the FalkorDB path and the Cypher that produced it. Flag reliance on a publisher notice. Do not call the draft wrong, and do not call an Expression of Concern a retraction. Depth is 1..3. Depth 4 is not implemented.",
  "tools": [
    {
      "tool": "check_answer",
      "description": "Call this before shipping a health-AI draft. Pass the draft text and cited URLs. Returns pass (ships), warn (human review), or block (fail the build), plus the FalkorDB algo.SPpaths route and Cypher. warn: counted path to an Expression of Concern, unverified hop, unfinished check, or no verifiable source. block: counted path to a retraction, withdrawal, or removal. exit_code 3 is infrastructure failure. Depth 1-3.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "text": {
            "default": "",
            "description": "Draft or fixture text to check.",
            "title": "Text",
            "type": "string"
          },
          "urls": {
            "anyOf": [
              {
                "items": {
                  "type": "string"
                },
                "type": "array"
              },
              {
                "type": "null"
              }
            ],
            "default": null,
            "description": "Cited source URLs from the draft.",
            "title": "Urls"
          },
          "engine": {
            "default": "draft",
            "description": "Engine or fixture name for this draft.",
            "title": "Engine",
            "type": "string"
          },
          "depth": {
            "default": 2,
            "description": "Hop budget from 1 to 3.",
            "maximum": 3,
            "minimum": 1,
            "title": "Depth",
            "type": "integer"
          }
        },
        "title": "check_answerArguments"
      }
    },
    {
      "tool": "check_study",
      "description": "Look up one DOI or PMID. Returns publisher notices on that study and works/sources already in the graph that cite it. OpenAlex is_retracted can be false for an Expression of Concern.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "doi_or_pmid": {
            "description": "DOI or PMID of one study.",
            "title": "Doi Or Pmid",
            "type": "string"
          }
        },
        "required": [
          "doi_or_pmid"
        ],
        "title": "check_studyArguments"
      }
    },
    {
      "tool": "explain_path",
      "description": "Explain the deciding citation path. Same inputs as check_answer. Returns the algo.SPpaths call, path strength, hop sentences, and the Cypher that produced the verdict.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "text": {
            "default": "",
            "description": "Draft or fixture text to explain.",
            "title": "Text",
            "type": "string"
          },
          "urls": {
            "anyOf": [
              {
                "items": {
                  "type": "string"
                },
                "type": "array"
              },
              {
                "type": "null"
              }
            ],
            "default": null,
            "description": "Cited source URLs from the draft.",
            "title": "Urls"
          },
          "engine": {
            "default": "draft",
            "description": "Engine or fixture name for this draft.",
            "title": "Engine",
            "type": "string"
          },
          "depth": {
            "default": 2,
            "description": "Hop budget from 1 to 3.",
            "maximum": 3,
            "minimum": 1,
            "title": "Depth",
            "type": "integer"
          }
        },
        "title": "explain_pathArguments"
      }
    },
    {
      "tool": "recheck_affected",
      "description": "After what_rests_on, re-run check_answer on just the counted answers that rest on this notice. Use when a publisher notice changed and you need to know which shipped answers to revisit.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "doi": {
            "description": "Notice DOI or study DOI to recheck from.",
            "title": "Doi",
            "type": "string"
          },
          "depth": {
            "default": 2,
            "description": "Hop budget from 1 to 3.",
            "maximum": 3,
            "minimum": 1,
            "title": "Depth",
            "type": "integer"
          }
        },
        "required": [
          "doi"
        ],
        "title": "recheck_affectedArguments"
      }
    },
    {
      "tool": "rewrite_answer",
      "description": "After check_answer returns warn or block, rewrite only the sentences whose citations reach the flagged study, then re-run the check. Keeps every other sentence. Discloses the publisher notice or an on-topic sibling already in this answer's graph. Never invents a citation. Returns the first check, the rewritten text, the recheck, and exit_code matching the recheck.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "text": {
            "default": "",
            "description": "Draft that already failed the check.",
            "title": "Text",
            "type": "string"
          },
          "urls": {
            "anyOf": [
              {
                "items": {
                  "type": "string"
                },
                "type": "array"
              },
              {
                "type": "null"
              }
            ],
            "default": null,
            "description": "Cited source URLs from the draft.",
            "title": "Urls"
          },
          "engine": {
            "default": "draft",
            "description": "Engine or fixture name for this draft.",
            "title": "Engine",
            "type": "string"
          },
          "depth": {
            "default": 2,
            "description": "Hop budget from 1 to 3.",
            "maximum": 3,
            "minimum": 1,
            "title": "Depth",
            "type": "integer"
          }
        },
        "title": "rewrite_answerArguments"
      }
    },
    {
      "tool": "ro_cypher",
      "description": "Run read-only OpenCypher against the MoolTrace graph using FalkorDB GRAPH.RO_QUERY. Writes are rejected. A LIMIT is added when the query has RETURN and no LIMIT outside string literals. Rows are sliced to 50. timeout_ms is 100-15000.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "query": {
            "description": "Read-only OpenCypher to run.",
            "title": "Query",
            "type": "string"
          },
          "timeout_ms": {
            "default": 3000,
            "description": "Query timeout in milliseconds, 100-15000.",
            "maximum": 15000,
            "minimum": 100,
            "title": "Timeout Ms",
            "type": "integer"
          }
        },
        "required": [
          "query"
        ],
        "title": "ro_cypherArguments"
      }
    },
    {
      "tool": "shared_ancestors",
      "description": "Compare two drafts (by answer id or engine name) and return hub works that both use on a path to a publisher notice. First-hop counts are not a node-disjoint flow.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "answer_a": {
            "default": "",
            "description": "First answer id already in the graph.",
            "title": "Answer A",
            "type": "string"
          },
          "answer_b": {
            "default": "",
            "description": "Second answer id already in the graph.",
            "title": "Answer B",
            "type": "string"
          },
          "engine_a": {
            "default": "",
            "description": "Engine name if answer_a is omitted.",
            "title": "Engine A",
            "type": "string"
          },
          "engine_b": {
            "default": "",
            "description": "Engine name if answer_b is omitted.",
            "title": "Engine B",
            "type": "string"
          }
        },
        "title": "shared_ancestorsArguments"
      }
    },
    {
      "tool": "trace_answer",
      "description": "Ingest a draft or its source URLs, expand RESTS_ON in FalkorDB, and return every path that ends on a publisher notice, plus the Cypher. Does not decide pass/warn/block.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "text": {
            "default": "",
            "description": "Draft or fixture text to ingest.",
            "title": "Text",
            "type": "string"
          },
          "urls": {
            "anyOf": [
              {
                "items": {
                  "type": "string"
                },
                "type": "array"
              },
              {
                "type": "null"
              }
            ],
            "default": null,
            "description": "Cited source URLs to walk from.",
            "title": "Urls"
          },
          "engine": {
            "default": "draft",
            "description": "Engine or fixture name for this draft.",
            "title": "Engine",
            "type": "string"
          },
          "depth": {
            "default": 2,
            "description": "Hop budget from 1 to 3.",
            "maximum": 3,
            "minimum": 1,
            "title": "Depth",
            "type": "integer"
          }
        },
        "title": "trace_answerArguments"
      }
    },
    {
      "tool": "what_rests_on",
      "description": "Reverse impact after a notice changes. Given a notice DOI or a study DOI, return 'This Expression of Concern affects N stored answers' plus the counted answer ids (weighted PATH_RULE paths only). Then call recheck_affected to re-run those answers. This is not a monitoring or alert scheduler.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "doi": {
            "description": "Notice DOI or study DOI to reverse from.",
            "title": "Doi",
            "type": "string"
          }
        },
        "required": [
          "doi"
        ],
        "title": "what_rests_onArguments"
      }
    }
  ]
}
